css:
.ss-stages{margin-bottom:20px}
.ss-stage{display:grid;grid-template-columns:90px minmax(0,1fr);gap:4px 22px;border-top:1px solid var(--line);padding:20px 0}
.ss-stage:last-child{border-bottom:1px solid var(--line)}
.ss-stage__l{font:800 15px/1.3 var(--font-heading);color:var(--accent)}
.ss-stage__t{font:800 19px/1.3 var(--font-heading);color:var(--ink);text-transform:none;margin:0 0 6px}
.ss-stage__p{font-size:15px;line-height:1.7;color:var(--body-text);margin:0}
@media (max-width:640px){.ss-stage{grid-template-columns:minmax(0,1fr);gap:6px}}
